```rust
/// l5merge#1: a token pool's way back (`box:<t>`, holding its pool's token, here one a mix moved) is a box to merging.
#[test]
fn l5merge_1_a_token_pools_way_back_is_merged_as_a_box() {
    let w = world();
    let mut wrong = Vec::new();
    // A. O 5 ₳ made private; K a plain way back 9.71 ₳; W unknown making 9.71 ₳; T a token pool's way back, mixed, 4.15 ₳ + token.
    let o = owned(&w, 0x01, 0, 5_000_000, &[]);
    let k = owned(&w, 0x61, 0, BOX, &[]);
    let unplaced = owned(&w, 0x30, 0, BOX, &[]);
    let t = owned(&w, 0x70, 0, 4_150_000, &[("pooltoken", 1)]);
    println!("T adds {} lovelace (positive: not last)", build::adds(&w.chain.params, &t).unwrap());
    let known: Vec<(&UtxoResponse, Class)> = vec![
        (&o, class("public:0", Origin::Own)),
        (&k, class(&format!("box:{}", k.tx_hash), Origin::Lovejoin)),
        (&unplaced, class(&format!("box:{0}+unknown:{0}", unplaced.tx_hash), Origin::Lovejoin)),
        (&t, class(&format!("box:{}", t.tx_hash), Origin::Mixed)),
    ];
    let name_of = |u: &str| -> &'static str {
        [(&o, "O"), (&k, "K"), (&unplaced, "W"), (&t, "T")].iter().find(|(x, _)| one(x)[0] == u).map_or("?", |(_, n)| *n)
    };
    let seedelf = paying(16_000_000);
    for (name, purpose, pay) in [
        ("A: a Send of 16 ₳ to a Seedelf", Purpose::Pay, Vec::new()),
        ("A: a Make public of 16 ₳", Purpose::Pay, to_address(16_000_000)),
        ("A: a new session's funding of 11 ₳ and its 5 ₳ collateral", Purpose::Fund { session: Some("session:7".into()) }, funding(11_000_000)),
    ] {
        let spent = outpoints(&spent_by(&w, purpose, &known, &seedelf, &pay));
        let names: Vec<&str> = spent.iter().map(|u| name_of(u)).collect();
        let line = format!("{name}: spent {names:?}");
        println!("{line}");
        if spent.contains(&one(&unplaced)[0]) || !spent.contains(&one(&t)[0]) {
            wrong.push(format!("{line} (W, of unknown making, merged ahead of T, a mixed box)"));
        }
    }
    // B. O 5 ₳; K1, K2 plain 4.71 ₳; T a 9 ₳ token pool box's way back, mixed, 8.65 ₳ + token. 11 ₳ out: O+T pays with one box.
    let k1 = owned(&w, 0x62, 0, 4_710_000, &[]);
    let k2 = owned(&w, 0x63, 0, 4_710_000, &[]);
    let t = owned(&w, 0x71, 0, 8_650_000, &[("pooltoken", 1)]);
    let known: Vec<(&UtxoResponse, Class)> = vec![
        (&o, class("public:0", Origin::Own)),
        (&k1, class(&format!("box:{}", k1.tx_hash), Origin::Lovejoin)),
        (&k2, class(&format!("box:{}", k2.tx_hash), Origin::Lovejoin)),
        (&t, class(&format!("box:{}", t.tx_hash), Origin::Mixed)),
    ];
    let name_of = |u: &str| -> &'static str {
        [(&o, "O"), (&k1, "K1"), (&k2, "K2"), (&t, "T")].iter().find(|(x, _)| one(x)[0] == u).map_or("?", |(_, n)| *n)
    };
    let seedelf = paying(11_000_000);
    let one_box = outpoints(&[o.clone(), t.clone()]);
    build::transfer_from(&w.chain, &[o.clone(), t.clone()], std::slice::from_ref(&seedelf), &w.owner, w.signer)
        .unwrap().estimate().unwrap(); // O and T alone build
    for (name, purpose, pay) in [
        ("B: a Send of 11 ₳ to a Seedelf", Purpose::Pay, Vec::new()),
        ("B: a Make public of 11 ₳", Purpose::Pay, to_address(11_000_000)),
        ("B: a new session's funding of 6 ₳ and its 5 ₳ collateral", Purpose::Fund { session: Some("session:7".into()) }, funding(6_000_000)),
    ] {
        let spent = outpoints(&spent_by(&w, purpose, &known, &seedelf, &pay));
        let names: Vec<&str> = spent.iter().map(|u| name_of(u)).collect();
        let line = format!("{name}: spent {names:?}");
        println!("{line}");
        if spent != one_box { wrong.push(format!("{line} (two boxes where O and T, one box, pay)")); }
    }
    assert!(wrong.is_empty(), "a token pool's way back left out of the box order:\n{}", wrong.join("\n"));
}
