```rust
#[test]
fn a_send_one_transaction_of_u_and_w_paid_still_goes_in_one() {
    let w = world();
    let u = owned(&w, 0x01, 150 * ADA, &[("tok", 5)]);
    let big = owned(&w, 0x02, 199_700_000, &[]);
    let small: Vec<UtxoResponse> = (0..25u8).map(|i| owned(&w, 0x10 + i, 4_710_000, &[])).collect();
    let one = [paying(300 * ADA)];
    let two = [paying(150 * ADA), paying(150 * ADA)];
    let send_from = |inputs: &[UtxoResponse], payments: &[Payment]| {
        build::transfer_from(&w.chain, inputs, payments, &w.owner, w.signer).and_then(|s| s.estimate()).map(|_| ())
    };
    let with = |first: &UtxoResponse, k: usize| -> Vec<UtxoResponse> {
        std::iter::once(first.clone()).chain(small[..k].iter().cloned()).collect()
    };
    for payments in [&one[..], &two[..]] {
        send_from(&[u.clone(), big.clone()], payments).expect("U and W pay in one transaction");
        assert!(build::is_short(&send_from(&with(&u, 21), payments).unwrap_err()));
        assert!(build::is_too_many(&send_from(&with(&u, 22), payments).unwrap_err()));
        assert!(build::is_short(&send_from(&with(&big, 21), payments).unwrap_err()));
    }
    let mut wrong = Vec::new();
    for k_origin in [Origin::Mixed, Origin::Lovejoin] {
        let mut known = vec![(u.clone(), class("public:0", Origin::Own)),
            (big.clone(), class(&format!("box:{0}+unknown:{0}", big.tx_hash), Origin::Lovejoin))];
        known.extend(small.iter().map(|k| (k.clone(), class(&format!("box:{}", k.tx_hash), k_origin))));
        let available: Vec<UtxoResponse> = known.iter().map(|(u, _)| u.clone()).collect();
        let h = known.iter().fold(Histories::new(Purpose::Pay), |h, (u, c)| h.with(&u.tx_hash, u.tx_index, c.clone()));
        let public = |lovelace: u64| AddressPayment { to: ShelleyAddress::new(Network::Testnet,
            ShelleyPaymentPart::Key(PaymentKeyHash::new([7; 28])), ShelleyDelegationPart::Null).into(),
            lovelace, tokens: Assets::new() };
        let spends: [(&str, &[Payment], Vec<AddressPayment>); 3] = [
            ("a Send to one Seedelf, 300 ₳", &one[..], Vec::new()),
            ("a Send to two Seedelfs, 150 ₳ each", &two[..], Vec::new()),
            ("a Make public of 300 ₳", &[], vec![public(300 * ADA)])];
        for (name, payments, to_address) in spends {
            let built = if to_address.is_empty() {
                build::transfer_apart(&w.chain, &available, &h, payments, &w.owner, w.signer)
            } else {
                build::sweep_many_apart(&w.chain, &available, &h, &to_address, &w.owner, w.signer)
            };
            let line = match built {
                Ok(spend) if outpoints(&spend.inputs()) == outpoints(&[u.clone(), big.clone()]) => continue,
                Ok(spend) => format!("{name}, the small boxes {k_origin:?}: built with {} inputs", spend.inputs().len()),
                Err(e) => format!("{name}, the small boxes {k_origin:?}: refused, TooMany: {}: {e}", build::is_too_many(&e)),
            };
            wrong.push(line);
        }
    }
    assert!(wrong.is_empty(), "a Send U and W paid in one transaction no longer builds as one:\n{}", wrong.join("\n"));
}
