seedelf-platform/seedelf-core/tests/mint_test.rs, inside `mod apart` (it uses that module's helpers: BOX, class, owned, received_class, paying, to_address, funding, spent_by). It ran in a copy (now deleted) with: CARGO_TARGET_DIR=$HOME/.cache/seedelf-calls/r5-target-l5merge_3 nice -n 10 systemd-run --user --scope -q -p MemoryMax=8G -p MemorySwapMax=0 timeout 30m cargo test --offline -p seedelf-core --test mint_test at_the_same_box_count_a_mixed_box_takes_no_more_of_the_other_money

```rust
    /// Chunk 51, round five's last look, l5merge#3: where order c builds with a plain box, its choice of as many boxes
    /// with a mixed one regrows c's rest, so a mixed box smaller than the plain one takes more of the other money: more
    /// received payments (more payers tied to the spend, more script inputs' fee), or, for a funding, another session's
    /// money that the plain box's build left alone. 25 received payments of 2 ₳, P (a plain way back, 9.71 ₳) and M
    /// (mixed, 4.71 ₳): a Send or Make public of 43 ₳ takes no more received payments than P's build does; and beside 17
    /// received payments and 6 UTxOs of another session's money of 1.5 ₳, a new session's funding of 36 ₳ and its 5 ₳
    /// collateral takes none of that session's money, since P and the 17 pay.
    #[test]
    fn at_the_same_box_count_a_mixed_box_takes_no_more_of_the_other_money() {
        let w = world();
        let plain = owned(&w, 0x30, 0, BOX, &[]);
        let mixed = owned(&w, 0x40, 0, 4_710_000, &[]);
        let boxes_known = || -> Vec<(&UtxoResponse, Class)> {
            vec![
                (
                    &plain,
                    class(&format!("box:{}", plain.tx_hash), Origin::Lovejoin),
                ),
                (
                    &mixed,
                    class(&format!("box:{}", mixed.tx_hash), Origin::Mixed),
                ),
            ]
        };
        let builds = |inputs: &[UtxoResponse], seedelf: &Payment, pay: &[AddressPayment]| {
            if pay.is_empty() {
                build::transfer_from(
                    &w.chain,
                    inputs,
                    std::slice::from_ref(seedelf),
                    &w.owner,
                    w.signer,
                )
            } else {
                build::sweep_many_from(&w.chain, inputs, pay, &w.owner, w.signer)
            }
            .and_then(|s| s.estimate())
            .map(|_| ())
        };
        let with = |one: &UtxoResponse, others: &[UtxoResponse]| -> Vec<UtxoResponse> {
            std::iter::once(one.clone())
                .chain(others.iter().cloned())
                .collect()
        };
        let mut wrong = Vec::new();

        // A Send and a Make public of 43 ₳ over 25 received payments of 2 ₳.
        let received: Vec<(UtxoResponse, Class)> = (0..25u8)
            .map(|i| {
                let u = owned(&w, 0x50 + i, 0, 2_000_000, &[]);
                let c = received_class(&u);
                (u, c)
            })
            .collect();
        let payments: Vec<UtxoResponse> = received.iter().map(|(u, _)| u.clone()).collect();
        let seedelf = paying(43_000_000);
        for (name, pay) in [
            ("a Send of 43 ₳ to a Seedelf", Vec::new()),
            ("a Make public of 43 ₳", to_address(43_000_000)),
        ] {
            // The premises: the payments alone run into the input limit, P pays beside the fewest payments, and M
            // beside as many is short.
            assert!(
                build::is_too_many(&builds(&payments[..23], &seedelf, &pay).unwrap_err()),
                "{name}"
            );
            let beside_plain = (0..=payments.len())
                .find(|&n| builds(&with(&plain, &payments[..n]), &seedelf, &pay).is_ok())
                .unwrap();
            let short =
                builds(&with(&mixed, &payments[..beside_plain]), &seedelf, &pay).unwrap_err();
            assert!(build::is_short(&short), "{name}: {short}");
            let mut known = boxes_known();
            known.extend(received.iter().map(|(u, c)| (u, c.clone())));
            let spent = spent_by(&w, Purpose::Pay, &known, &seedelf, &pay);
            let paid_by_others = spent
                .iter()
                .filter(|u| payments.iter().any(|p| p.tx_hash == u.tx_hash))
                .count();
            let line = format!(
                "{name}: P pays beside {beside_plain} payments ({} inputs); spent {} inputs: P {}, M {}, {paid_by_others} payments",
                beside_plain + 1,
                spent.len(),
                spent.iter().any(|u| u.tx_hash == plain.tx_hash),
                spent.iter().any(|u| u.tx_hash == mixed.tx_hash),
            );
            println!("{line}");
            if paid_by_others > beside_plain {
                wrong.push(line);
            }
        }

        // A new session's funding of 36 ₳ and its 5 ₳ collateral over 17 received payments of 2 ₳ and 6 UTxOs of
        // another session's money of 1.5 ₳ (tier 1: taken only when nothing else pays).
        let seventeen: Vec<(UtxoResponse, Class)> = received[..17].to_vec();
        let others_session: Vec<(UtxoResponse, Class)> = (0..6u64)
            .map(|i| {
                let u = owned(&w, 0x90, i, 1_500_000, &[]);
                (u, class("session:3", Origin::Session))
            })
            .collect();
        let pay = funding(36_000_000);
        let tier0: Vec<UtxoResponse> = seventeen.iter().map(|(u, _)| u.clone()).collect();
        let mut by_count: Vec<UtxoResponse> = tier0.clone();
        by_count.extend(others_session.iter().take(6).map(|(u, _)| u.clone()));
        // The premises: in a's order (the 17, then the session's money) 22 are short and 23 too many; P and the 17
        // pay; M and the 17 are short.
        assert!(build::is_short(
            &builds(&by_count[..22], &seedelf, &pay).unwrap_err()
        ));
        assert!(build::is_too_many(
            &builds(&by_count[..23], &seedelf, &pay).unwrap_err()
        ));
        builds(&with(&plain, &tier0), &seedelf, &pay).expect("P and the 17 pay");
        assert!(build::is_short(
            &builds(&with(&mixed, &tier0), &seedelf, &pay).unwrap_err()
        ));
        let mut known = boxes_known();
        known.extend(seventeen.iter().map(|(u, c)| (u, c.clone())));
        known.extend(others_session.iter().map(|(u, c)| (u, c.clone())));
        let spent = spent_by(
            &w,
            Purpose::Fund {
                session: Some("session:7".into()),
            },
            &known,
            &seedelf,
            &pay,
        );
        let sessions = spent
            .iter()
            .filter(|u| u.tx_hash == hex::encode([0x90u8; 32]))
            .count();
        let line = format!(
            "a new session's funding of 36 ₳ and its 5 ₳ collateral: spent {} inputs: P {}, M {}, {sessions} of another session's money",
            spent.len(),
            spent.iter().any(|u| u.tx_hash == plain.tx_hash),
            spent.iter().any(|u| u.tx_hash == mixed.tx_hash),
        );
        println!("{line}");
        if sessions > 0 {
            wrong.push(line);
        }
        assert!(
            wrong.is_empty(),
            "the mixed box's choice took more of the other money than the plain box's build:\n{}",
            wrong.join("\n")
        );
    }
