    const line = policy.find((l) => l.includes(marker));
    if (!line) return `(no line with ${marker})`;
    const at = line.indexOf(start);
    if (at < 0) return `(no "${start}")`;
    const rest = line.slice(at);
    const ends = [rest.indexOf("; "), rest.indexOf(". ")].filter((i) => i > 0);
    return ends.length ? rest.slice(0, Math.min(...ends)) : rest;
  };
