import { describe, expect, it } from "vitest";
import type { DappSession } from "../src/background/dapp";
import { APIError } from "../src/shared/dapp";
import { testBalances, vectors } from "./fakes";

const PASSWORD = "correct horse battery";
const account = vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === 12)!;
const ORIGIN = "https://app.example.com";
const NOT_CONNECTED = { code: APIError.Refused, info: "This site isn't connected to Seedelf Wallet. Call enable() first." };
const DECLINED_WAIT = { code: APIError.Refused, info: "The user declined this site just now. It can ask again in 10 s." };
let pages = 0;
const page = (origin = ORIGIN): DappSession => ({ id: `l5s1-${++pages}`, origin, title: "Example" });
async function until(check: () => boolean) {
  for (let i = 0; i < 200 && !check(); i++) await new Promise((r) => setTimeout(r, 0));
  expect(check()).toBe(true);
}
async function on() {
  const t = testBalances();
  await t.wallet.create(account.phrase, PASSWORD);
  await t.preferences.set({ dappConnector: true, spendRewards: false });
  return t;
}
type T = Awaited<ReturnType<typeof on>>;
async function connect(t: T) {
  const s = page();
  const enabling = t.dapp.call(s, "enable", []);
  await until(() => t.dapp.approvals().length === 1);
  await t.dapp.answer(t.dapp.approvals()[0]!.id, true);
  expect(await enabling).toBe(true);
}
/** `n` reloads in a row: each new page's call, then the page leaving once the window shows. What each one met. */
async function reloads(t: T, method: "enable" | "signData", n: number): Promise<unknown[]> {
  const heard: unknown[] = [];
  for (let i = 0; i < n; i++) {
    const s = page();
    const shown = t.dappWindow.shown;
    let said: unknown;
    const args = method === "enable" ? [] : [t.deps.wasm.cip30Address(account.preprod.receive_0 as string), "00"];
    const calling = t.dapp.call(s, method, args).then(() => (said = "answered"), (e: { failure: unknown }) => (said = e.failure));
    for (let k = 0; k < 200 && said === undefined && t.dappWindow.shown === shown; k++) await new Promise((r) => setTimeout(r, 0));
    if (said === undefined) {
      const wasShown = t.dappWindow.shown > shown;
      t.dapp.gone(s);
      await calling;
      said = wasShown ? "window shown" : "neither";
    }
    heard.push(said);
  }
  return heard;
}
