                inputs,
                std::slice::from_ref(&seedelf),
                &w.owner,
                w.signer,
            )
            .and_then(|s| s.estimate().map(|f| f.fee.total))
        };
        // The fewest payments beside `b` that pay a Send, and its fee.
        let fewest = |b: &UtxoResponse| -> (usize, u64) {
            (0..=21)
                .find_map(|n| send_from(&with(b, n)).ok().map(|fee| (n, fee)))
                .unwrap()
        };
        // The premise: X pays only beside 21 payments, and beside 22 is more than one transaction spends.
        assert!(build::is_short(&send_from(&with(&mixed, 20)).unwrap_err()));
        assert!(build::is_too_many(&send_from(&with(&mixed, 22)).unwrap_err()));
        let (x_n, x_fee) = fewest(&mixed);
        println!("a Send: X and {x_n} payments ({} inputs), fee {x_fee}", x_n + 1);
        let mut wrong = Vec::new();
        for (box_name, plain, plain_class) in [("L", &l, l_class), ("P", &p, p_class)] {
            let (n, fee) = fewest(plain);
            println!("a Send: {box_name} and {n} payments ({} inputs), fee {fee}", n + 1);
            let mut known: Vec<(&UtxoResponse, Class)> =
                vec![(plain, plain_class), (&mixed, mixed_class.clone())];
            known.extend(received.iter().map(|(u, c)| (u, c.clone())));
            for (name, purpose, pay) in [
                ("a Send of 43 ₳ to a Seedelf", Purpose::Pay, Vec::new()),
                ("a Make public of 43 ₳", Purpose::Pay, to_address(43_000_000)),
                (
                    "a new session's funding of 38 ₳ and its 5 ₳ collateral",
                    Purpose::Fund { session: Some("session:7".into()) },
                    funding(38_000_000),
                ),
            ] {
                let spent = outpoints(&spent_by(&w, purpose, &known, &seedelf, &pay));
                let (b, x) = (&one(plain)[0], &one(&mixed)[0]);
                let line = format!(
                    "{name}, beside {box_name}: {} inputs, spent {box_name}: {}, spent X: {}",
                    spent.len(), spent.contains(b), spent.contains(x)
                );
                println!("{line}");
                if spent.len() > n + 1 || !spent.contains(b) || spent.contains(x) {
                    wrong.push(line);
                }
            }
        }
        assert!(
            wrong.is_empty(),
            "a mixed box went first by merging more of the other UTxOs than the plain one needs:\n{}",
            wrong.join("\n")
        );
    }
