```rust
    /// l5still#3: one box that pays alone ranks P, a plain way back (`box:<p>`, origin lovejoin), level with W, a box of
    /// unknown making (`box:<w>+unknown:<w>`, origin lovejoin), and takes the smaller. Merging (`box_rank`) and the
    /// escape hatch (`knownBox`) take P before W. Expect P alone for every purpose, whatever the sizes.
    #[test]
    fn l5still_3_one_box_paying_takes_a_plain_box_before_one_of_unknown_making_whatever_the_sizes() {
        let w = world();
        let seedelf = paying(3_000_000);
        let spends: Vec<(&str, Purpose, Vec<AddressPayment>)> = vec![
            ("a new session's funding of 2 ₳ and its 5 ₳ collateral",
             Purpose::Fund { session: Some("session:7".into()) }, funding(2_000_000)),
            ("a site's top-up of 2 ₳", Purpose::Fund { session: Some("session:3".into()) }, to_address(2_000_000)),
            ("a Make public of 3 ₳", Purpose::Pay, to_address(3_000_000)),
            ("a Send of 3 ₳ to a Seedelf", Purpose::Pay, Vec::new()),
        ];
        let mut wrong: Vec<String> = Vec::new();
        for unplaced_smaller in [true, false] {
            let (unplaced_lovelace, plain_lovelace) =
                if unplaced_smaller { (BOX - 300, BOX) } else { (BOX, BOX - 300) };
            let unplaced = owned(&w, 0x30, 0, unplaced_lovelace, &[]);
            let plain = owned(&w, 0x41, 0, plain_lovelace, &[]);
            let unplaced_class = class(&format!("box:{0}+unknown:{0}", unplaced.tx_hash), Origin::Lovejoin);
            let plain_class = class(&format!("box:{}", plain.tx_hash), Origin::Lovejoin);
            // Merging already tells them apart: P before W.
            assert!(build::box_rank(&plain_class) < build::box_rank(&unplaced_class));
            let known = [(&unplaced, unplaced_class), (&plain, plain_class)];
            for (name, purpose, pay) in &spends {
                let spent = outpoints(&spent_by(&w, purpose.clone(), &known, &seedelf, pay));
                let h = histories(purpose.clone(), &known);
                println!("{name}, W smaller: {unplaced_smaller}: ranks W {} P {}; spent W: {}, spent P: {}",
                    h.rank_of(&unplaced), h.rank_of(&plain), spent == one(&unplaced), spent == one(&plain));
                if spent != one(&plain) { wrong.push(format!("{name}, W smaller: {unplaced_smaller}: spent W")); }
            }
            let spent = minted(&w, &known);
            println!("a stealth mint, W smaller: {unplaced_smaller}: spent W: {}, spent P: {}",
                spent == one(&unplaced), spent == one(&plain));
            if spent != one(&plain) { wrong.push(format!("a stealth mint, W smaller: {unplaced_smaller}: spent W")); }
        }
        assert!(wrong.is_empty(), "spent W where P pays alone:\n{}", wrong.join("\n"));
    }
