```rust
    #[test]
    fn l5still_4_a_merge_spends_no_more_boxes_than_the_fewest_that_pay() {
        let w = world();
        let unplaced = owned(&w, 0x30, 0, BOX, &[]);
        let unplaced_class = class(&format!("box:{0}+unknown:{0}", unplaced.tx_hash), Origin::Lovejoin);
        let seedelf = paying(12_000_000);
        let mut wrong = Vec::new();
        for others_mixed in [[false, false], [true, false], [true, true]] {
            let others: Vec<(UtxoResponse, Class)> = others_mixed.iter().zip(0u8..).map(|(&mixed, i)| {
                let u = owned(&w, 0x40 + i, 0, 4_710_000, &[]);
                let origin = if mixed { Origin::Mixed } else { Origin::Lovejoin };
                (u.clone(), class(&format!("box:{}", u.tx_hash), origin))
            }).collect();
            let mut known: Vec<(&UtxoResponse, Class)> = others.iter().map(|(u, c)| (u, c.clone())).collect();
            known.push((&unplaced, unplaced_class.clone()));
            // The fewest that pay: W and one other, built from exactly those two.
            let two = vec![unplaced.clone(), others[0].0.clone()];
            for (name, purpose, pay) in [
                ("a new session's funding of 7 ₳ and its 5 ₳ collateral",
                 Purpose::Fund { session: Some("session:7".into()) }, funding(7_000_000)),
                ("a Make public of 12 ₳", Purpose::Pay, to_address(12_000_000)),
                ("a Send of 12 ₳ to a Seedelf", Purpose::Pay, Vec::new()),
            ] {
                let fee_of = |inputs: &[UtxoResponse]| if pay.is_empty() {
                    build::transfer_from(&w.chain, inputs, std::slice::from_ref(&seedelf), &w.owner, w.signer)
                } else {
                    build::sweep_many_from(&w.chain, inputs, &pay, &w.owner, w.signer)
                }.and_then(|s| s.estimate().map(|e| e.fee.total));
                let fewest_fee = fee_of(&two).expect("W and one other pay");
                let spent = spent_by(&w, purpose.clone(), &known, &seedelf, &pay);
                let h = histories(purpose, &known);
                let spent_fee = fee_of(&spent).unwrap();
                let line = format!("{name}, the others mixed: {others_mixed:?}: spent {} boxes, W among them: {} (merged {} classes, fee {spent_fee}), where W and one other pay (fee {fewest_fee}): {} lovelace more fee",
                    spent.len(), outpoints(&spent).contains(&one(&unplaced)[0]), h.merged(&spent).len(),
                    spent_fee as i64 - fewest_fee as i64);
                println!("{line}");
                if spent.len() > two.len() { wrong.push(line); }
            }
        }
        assert!(wrong.is_empty(), "a merge spent more boxes together than the fewest that pay:\n{}", wrong.join("\n"));
    }
